}

function label(txt, x, y, opts) {
  opts = opts || {};
  var t = draw.text(txt)
    .font({ family: opts.family || 'Georgia, Times New Roman, serif', size: opts.size || 23, anchor: opts.anchor || 'middle' })
    .fill(opts.fill || '#000');
  if (opts.italic) t.font({ style: 'italic' });
  t.center(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opts.halo == null ? 4 : opts.halo, 'stroke-linejoin': 'round' });
