}

function dashedLine(x1, y1, x2, y2, color) {
  return draw.line(x1, y1, x2, y2).stroke({ color: color, width: 2, dasharray: '10 8', linecap: 'round' });
}

function arrowHead(x, y, angle, size, color) {
  var p1x = x, p1y = y;
  var p2x = x - size * Math.cos(angle - 0.45), p2y = y - size * Math.sin(angle - 0.45);
  var p3x = x - size * Math.cos(angle + 0.45), p3y = y - size * Math.sin(angle + 0.45);
  return draw.polygon([[p1x, p1y], [p2x, p2y], [p3x, p3y]]).fill(color || '#000').stroke('none');
}

function doubleArrow(x1, y1, x2, y2, color) {
  var line = draw.line(x1, y1, x2, y2).stroke({ color: color, width: 1.6, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  arrowHead(x2, y2, ang, 7, color);
  arrowHead(x1, y1, ang + Math.PI, 7, color);
  return line;
}

function dot(x, y, r, fill, stroke) {
  return draw.circle(2 * r).center(x, y).fill(fill).stroke({ color: stroke || '#111', width: 0.8 });
