function arrowHead(x, y, angle, size, color) {
  var p2x = x - size * Math.cos(angle - 0.48);
  var p2y = y - size * Math.sin(angle - 0.48);
  var p3x = x - size * Math.cos(angle + 0.48);
  var p3y = y - size * Math.sin(angle + 0.48);
  return draw.polygon([[x, y], [p2x, p2y], [p3x, p3y]]).fill(color).stroke('none');
