function drawAxisLine(x1, y1, x2, y2) {
  var line = draw.line(x1, y1, x2, y2).stroke({ color: '#000', width: 2.1, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  arrowHead(x2, y2, ang, 15, '#000');
  arrowHead(x1, y1, ang + Math.PI, 15, '#000');
  return line;
}

function dashedAxis(x1, y1, x2, y2) {
  return draw.line(x1, y1, x2, y2)
    .stroke({ color: '#ff0000', width: 2, dasharray: '13 10', linecap: 'butt' });
