    .font({
      family: opts.family || 'Georgia, Times New Roman, serif',
      size: opts.size || 28,
      anchor: opts.anchor || 'middle',
      style: opts.italic ? 'italic' : 'normal'
    })
    .fill(opts.fill || '#000');
  t.center(x, y);
  t.attr({
    'paint-order': 'stroke',
    stroke: opts.noHalo ? 'none' : '#fff',
    'stroke-width': opts.noHalo ? 0 : (opts.halo == null ? 5 : opts.halo),
    'stroke-linejoin': 'round'
  });
