}

function ellipsePolyline(a, b) {
  var pts = [];
  for (var i = 0; i <= 320; i++) {
    var t = 2 * Math.PI * i / 320;
    pts.push([sx(a * Math.cos(t)), sy(b * Math.sin(t))]);
