function renderFigure() {
  draw.clear();

  var a = state.a;
  var b = Math.min(state.b, a - 0.5);
  var c = Math.sqrt(Math.max(0, a * a - b * b));

  var leftV = [sx(-a), CY], rightV = [sx(a), CY];
  var topC = [CX, sy(b)], botC = [CX, sy(-b)];
  var leftF = [sx(-c), CY], rightF = [sx(c), CY];

  draw.rect(W, H).fill('#fff');

  var xAxis = drawAxisLine(44, CY, 856, CY);
  var yAxis = drawAxisLine(CX, 30, CX, 455);
  makeInteractive(xAxis, 'The horizontal x-axis contains the center, vertices, and foci.', 'Horizontal axis', 'Because this is a horizontal ellipse, its major axis lies on the x-axis. The vertices and foci all move along this line as a and b change.');
  makeInteractive(yAxis, 'The vertical y-axis contains the co-vertices.', 'Vertical axis', 'The minor axis is perpendicular to the major axis. Its endpoints are the co-vertices, a distance b above and below the center.');

  var major = dashedAxis(leftV[0], CY, rightV[0], CY);
  var minor = dashedAxis(CX, botC[1], CX, topC[1]);
  makeInteractive(major, 'Major axis length = 2a', 'Major axis', 'The major axis is the longest diameter of this horizontal ellipse. It runs from the left vertex (-a,0) to the right vertex (a,0).');
  makeInteractive(minor, 'Minor axis length = 2b', 'Minor axis', 'The minor axis runs from (0,-b) to (0,b). Moving the b slider changes this vertical diameter.');

  var ell = draw.polyline(ellipsePolyline(a, b))
    .fill('none')
    .stroke({ color: '#00739f', width: 3.2, linecap: 'round', linejoin: 'round' });
  makeInteractive(ell, 'Ellipse: x²/a² + y²/b² = 1', 'Horizontal ellipse', 'The outline stays centered at the origin. The value a controls the horizontal radius, while b controls the vertical radius.');

  dot(CX, CY, 5.5, '#000', '#000', 'Center: (0,0)', 'Center', 'The center stays fixed at the origin. The sliders change distances measured from this fixed point.');
  dot(leftV[0], leftV[1], 4.8, '#111', '#111', 'Left vertex: (-a,0)', 'Vertex', 'Each vertex is a units from the center along the major axis.');
  dot(rightV[0], rightV[1], 4.8, '#111', '#111', 'Right vertex: (a,0)', 'Vertex', 'Increasing a moves the vertices farther from the center and widens the ellipse.');
  dot(topC[0], topC[1], 4.8, '#111', '#111', 'Top co-vertex: (0,b)', 'Co-vertex', 'Each co-vertex is b units from the center along the minor axis.');
  dot(botC[0], botC[1], 4.8, '#111', '#111', 'Bottom co-vertex: (0,-b)', 'Co-vertex', 'Changing b changes the height of the ellipse.');
  dot(leftF[0], leftF[1], 4.7, '#20d331', '#16851e', 'Left focus: (-c,0)', 'Focus', 'The focus distance is determined by c² = a² - b², so the foci are not placed independently.');
  dot(rightF[0], rightF[1], 4.7, '#20d331', '#16851e', 'Right focus: (c,0)', 'Focus', 'For fixed a, increasing b makes c smaller, so the foci move inward.');

  textLabel('x', 876, CY - 1, { size: 29, italic: true, halo: 4 });
  textLabel('y', CX + 8, 17, { size: 29, italic: true, halo: 4 });

  if (!state.paramMode) {
    var leftVertexX = Math.max(40, leftV[0] - 42);
    var rightVertexX = Math.min(W - 43, rightV[0] + 44);

    textLabel('Vertex', leftVertexX, CY - 21, { size: 28 });
    textLabel('Vertex', rightVertexX, CY - 23, { size: 28 });

    textLabel('Focus', leftF[0], CY - 28, { size: 28 });
    textLabel('Focus', rightF[0] - 2, CY - 28, { size: 28 });

    textLabel('Co-vertex', CX + 74, topC[1] - 16, { size: 28 });
    textLabel('Co-vertex', CX + 78, botC[1] + 23, { size: 28 });

    textLabel('Center', CX + 55, CY + 28, { size: 28 });
    textLabel('Major Axis', CX - 145, CY + 28, { size: 28 });
    textLabel('Minor Axis', CX + 88, (CY + topC[1]) / 2 + 2, { size: 28 });
  } else {
    var blue = '#155a9f';
    var orange = '#d46b08';
    var green = '#16851e';

    makeInteractive(doubleArrow(CX, CY + 38, rightV[0], CY + 38, blue), 'a is the horizontal radius.', 'Semi-major axis a', 'The distance from the center to a vertex is a. In the equation, a appears under x² because the major axis is horizontal.');
    textLabel('a', (CX + rightV[0]) / 2, CY + 62, { size: 26, fill: blue });

    makeInteractive(doubleArrow(CX - 35, CY, CX - 35, topC[1], orange), 'b is the vertical radius.', 'Semi-minor axis b', 'The distance from the center to a co-vertex is b. In the equation, b appears under y².');
    textLabel('b', CX - 61, (CY + topC[1]) / 2, { size: 26, fill: orange });

    makeInteractive(doubleArrow(CX, CY - 38, rightF[0], CY - 38, green), 'c is the focus distance.', 'Focus distance c', 'The foci are c units from the center, where c² = a² - b². This means c depends on a and b.');
    textLabel('c', (CX + rightF[0]) / 2, CY - 63, { size: 26, fill: green });

    textLabel('(±a, 0)', rightV[0] - 10, CY - 29, { size: 22, anchor: 'end', fill: blue });
    textLabel('(-a, 0)', leftV[0] + 66, CY + 31, { size: 22, fill: blue });

    textLabel('(0, b)', CX + 70, topC[1] - 16, { size: 22, fill: orange });
    textLabel('(0, -b)', CX + 72, botC[1] + 22, { size: 22, fill: orange });

    textLabel('(c, 0)', rightF[0] + 63, CY + 31, { size: 22, fill: green });
    textLabel('(-c, 0)', leftF[0] - 63, CY + 31, { size: 22, fill: green });

    textLabel('x²/a² + y²/b² = 1', 220, 424, { size: 25, fill: '#111' });
    textLabel('c² = a² - b²', 692, 424, { size: 25, fill: '#111' });
    textLabel('Center', CX + 55, CY + 29, { size: 25 });
  }
}

function syncInputs() {
  var aIn = document.getElementById('semiMajorAxisInput');
  var bIn = document.getElementById('semiMinorAxisInput');
  var lIn = document.getElementById('labelModeInput');
  var aVal = document.getElementById('semiMajorAxisVal');
  var bVal = document.getElementById('semiMinorAxisVal');
  if (aIn) aIn.value = state.a;
  if (bIn) bIn.value = state.b;
  if (lIn) lIn.checked = state.paramMode;
  if (aVal) aVal.value = state.a;
  if (bVal) bVal.value = state.b;
}

function update_semiMajorAxis(v) {
  state.a = v;
  if (state.b >= state.a) state.b = state.a - 0.5;
  syncInputs();
  sliderTeaching('Increasing a stretches the ellipse horizontally: the vertices move outward and c changes because c² = a² - b².');
  renderFigure();
}

function update_semiMinorAxis(v) {
  state.b = Math.min(v, state.a - 0.5);
  syncInputs();
  sliderTeaching('Increasing b makes the ellipse taller and, for a fixed a, brings the foci closer to the center.');
  renderFigure();
}

function toggle_labelMode(on) {
  state.paramMode = !!on;
  sliderTeaching(on ? 'Parameter labels show that a and b are the axis radii, while c is computed from c² = a² - b².' : 'Feature labels name the center, vertices, co-vertices, foci, and the two axes.');
  renderFigure();
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var st = demoSteps[state.step].state;
  state.a = st.semiMajorAxis;
  state.b = st.semiMinorAxis;
  state.paramMode = st.labelMode === 'Equation parameters';
  syncInputs();

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = demoSteps[state.step].narration;
  if (label) label.textContent = (state.step + 1) + '/' + demoSteps.length;
  renderFigure();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

